/**
 * Venturelyx :: Grow sending domain — expected DNS records and live
 * verification.
 *
 * SPF and DMARC are values we can predict exactly (SPF depends only on
 * which provider relays mail for this domain; DMARC is the org's own
 * policy choice, not provider-specific) — verify() compares what it finds
 * against those. DKIM is different: the actual public key is generated by
 * the sending provider's own systems (Google Admin console, a Spacemail
 * control panel, ...), so there is no value this code could predict in
 * advance. For DKIM, verify() only confirms a record exists in the right
 * place and is shaped like a real DKIM key — never invents an "expected"
 * key value, which would just be wrong.
 */
import { resolveCname, resolveTxt } from 'node:dns/promises';

export type SendingDomainProvider = 'spacemail' | 'google' | 'microsoft' | 'other';

export interface ExpectedRecord {
  type: 'SPF' | 'DKIM' | 'DMARC';
  kind: 'TXT' | 'CNAME';
  /** Full DNS record name, e.g. "example.com" or "_dmarc.example.com". */
  name: string;
  /** The literal value to create, when we can predict it (SPF, DMARC).
   *  Null for DKIM — see file header. */
  value: string | null;
  /** Free-text guidance shown alongside the record — where to get the
   *  real value (DKIM) or what it does (SPF/DMARC). */
  instructions: string;
}

// The mechanism each provider's own sending relay needs in SPF. 'other'
// has none we can know in advance — the record shown is a fill-in-the-blank
// template, not something verify() can check for an exact match against.
const SPF_INCLUDE: Partial<Record<SendingDomainProvider, string>> = {
  spacemail: 'spf.spacemail.com',
  google: '_spf.google.com',
  microsoft: 'spf.protection.outlook.com',
};

// DKIM selector convention per provider. Microsoft 365 publishes DKIM via
// two CNAMEs (selector1/selector2._domainkey) that Microsoft hosts and
// rotates itself, not a TXT record the org pastes in — everyone else uses
// a single TXT record at <selector>._domainkey.
const DKIM_SELECTOR: Record<SendingDomainProvider, string> = {
  spacemail: 'spacemail', google: 'google', microsoft: 'selector1', other: 'default',
};

const DKIM_INSTRUCTIONS: Record<SendingDomainProvider, string> = {
  spacemail: 'In your Spacemail control panel, open Domain settings → DKIM, enable it, and copy the exact ' +
    'TXT record it generates — the key itself is generated by Spacemail, not something to type in by hand.',
  google: 'In Google Admin console, go to Apps → Google Workspace → Gmail → Authenticate email, generate a ' +
    'new record, and copy the exact TXT value it gives you.',
  microsoft: 'In Microsoft 365 Defender, go to Email & collaboration → Policies & rules → DKIM, and enable it ' +
    'for this domain. Microsoft manages the key itself via two CNAME records (selector1/selector2._domainkey) ' +
    'pointing at a Microsoft-hosted key — there is no TXT value to copy.',
  other: "Check your email provider's own DKIM setup instructions — the selector name and record shape vary " +
    'by provider.',
};

const DMARC_POLICY_RE = /p=(\w+)/i;

function normalizeDomain(domain: string): string {
  return domain.trim().toLowerCase().replace(/\.$/, '');
}

export function buildExpectedRecords(domain: string, provider: SendingDomainProvider): ExpectedRecord[] {
  const d = normalizeDomain(domain);
  const spfInclude = SPF_INCLUDE[provider];
  const dkimSelector = DKIM_SELECTOR[provider];

  const spf: ExpectedRecord = {
    type: 'SPF', kind: 'TXT', name: d,
    value: spfInclude ? `v=spf1 include:${spfInclude} ~all` : 'v=spf1 include:<your provider’s SPF include> ~all',
    instructions: spfInclude
      ? `Authorizes ${provider}'s mail servers to send as ${d}.`
      : "Ask your email provider for their SPF include mechanism and use it in place of the placeholder above.",
  };

  const dkim: ExpectedRecord = provider === 'microsoft'
    ? {
        type: 'DKIM', kind: 'CNAME', name: `selector1._domainkey.${d}`,
        value: null, instructions: DKIM_INSTRUCTIONS.microsoft,
      }
    : {
        type: 'DKIM', kind: 'TXT', name: `${dkimSelector}._domainkey.${d}`,
        value: null, instructions: DKIM_INSTRUCTIONS[provider],
      };

  const dmarc: ExpectedRecord = {
    type: 'DMARC', kind: 'TXT', name: `_dmarc.${d}`,
    value: `v=DMARC1; p=quarantine; pct=100; rua=mailto:dmarc@${d}`,
    instructions: 'Tells receiving mail servers what to do with mail that fails SPF/DKIM, and where to send ' +
      'aggregate reports. Starting at p=quarantine (not p=reject) is the safer default while warming up.',
  };

  return [spf, dkim, dmarc];
}

async function lookupTxt(name: string): Promise<string[]> {
  try {
    const chunks = await resolveTxt(name);
    return chunks.map((c) => c.join(''));
  } catch {
    return [];
  }
}

async function lookupCname(name: string): Promise<string[]> {
  try {
    return await resolveCname(name);
  } catch {
    return [];
  }
}

export interface RecordCheckResult {
  type: 'SPF' | 'DKIM' | 'DMARC';
  ok: boolean;
  expected: string | null;
  found: string[];
  note: string;
}

async function checkSpf(domain: string, provider: SendingDomainProvider): Promise<RecordCheckResult> {
  const expected = buildExpectedRecords(domain, provider).find((r) => r.type === 'SPF')!;
  const found = (await lookupTxt(domain)).filter((r) => r.toLowerCase().startsWith('v=spf1'));
  const include = SPF_INCLUDE[provider];

  if (found.length === 0) {
    return { type: 'SPF', ok: false, expected: expected.value, found: [], note: `No SPF record found at ${domain}.` };
  }
  if (include) {
    const ok = found.some((r) => r.toLowerCase().includes(`include:${include}`));
    return {
      type: 'SPF', ok, expected: expected.value, found,
      note: ok
        ? `SPF record found and authorizes ${provider}.`
        : `An SPF record exists but doesn't include ${include} — mail sent through ${provider} will fail SPF.`,
    };
  }
  // 'other': we have no specific include to check for — presence of a
  // syntactically valid record is the only thing we can honestly confirm.
  return { type: 'SPF', ok: true, expected: expected.value, found, note: 'SPF record found.' };
}

async function checkDkim(domain: string, provider: SendingDomainProvider): Promise<RecordCheckResult> {
  const expected = buildExpectedRecords(domain, provider).find((r) => r.type === 'DKIM')!;

  if (provider === 'microsoft') {
    const [s1, s2] = await Promise.all([
      lookupCname(`selector1._domainkey.${domain}`),
      lookupCname(`selector2._domainkey.${domain}`),
    ]);
    const found = [...s1, ...s2];
    const ok = s1.length > 0 && s2.length > 0;
    return {
      type: 'DKIM', ok, expected: null, found,
      note: ok
        ? 'Both DKIM CNAME records resolve.'
        : `Missing ${s1.length === 0 ? 'selector1._domainkey' : ''}${s1.length === 0 && s2.length === 0 ? ' and ' : ''}${s2.length === 0 ? 'selector2._domainkey' : ''} — Microsoft can't sign mail for this domain until both exist.`,
    };
  }

  const selector = DKIM_SELECTOR[provider];
  const found = await lookupTxt(`${selector}._domainkey.${domain}`);
  const ok = found.some((r) => /v=dkim1/i.test(r) && /p=/i.test(r));
  return {
    type: 'DKIM', ok, expected: null, found,
    note: ok
      ? 'A DKIM key is published at the expected selector.'
      : `No valid DKIM record found at ${selector}._domainkey.${domain}. ${expected.instructions}`,
  };
}

async function checkDmarc(domain: string): Promise<RecordCheckResult> {
  const expected = buildExpectedRecords(domain, 'other').find((r) => r.type === 'DMARC')!;
  const found = await lookupTxt(`_dmarc.${domain}`);
  const record = found.find((r) => /v=dmarc1/i.test(r));
  const ok = !!record && DMARC_POLICY_RE.test(record);
  return {
    type: 'DMARC', ok, expected: expected.value, found,
    note: ok
      ? `DMARC record found (${record!.match(DMARC_POLICY_RE)![0]}).`
      : found.length > 0
        ? 'A record exists at _dmarc but is not a valid DMARC record.'
        : `No DMARC record found at _dmarc.${domain}.`,
  };
}

/** RFC 7489: a subdomain with no DMARC record of its own inherits the
 *  organizational domain's policy. Heuristic for "organizational domain" —
 *  last two labels — since resolving the true public-suffix boundary needs
 *  a full PSL; wrong only for domains under a multi-label public suffix
 *  (e.g. co.uk), which is a rare shape for a sending domain. */
export async function checkSubdomainInheritance(domain: string, ownDmarcFound: string[]): Promise<string | null> {
  if (ownDmarcFound.length > 0) return null;
  const parts = normalizeDomain(domain).split('.');
  if (parts.length <= 2) return null;
  const parent = parts.slice(-2).join('.');

  const parentRecords = await lookupTxt(`_dmarc.${parent}`);
  const parentDmarc = parentRecords.find((r) => /v=dmarc1/i.test(r));
  const policy = parentDmarc?.match(DMARC_POLICY_RE)?.[1]?.toLowerCase();
  if (!policy || policy === 'none') return null;

  return `${domain} has no DMARC record of its own. Subdomains inherit the organizational domain's policy when ` +
    `they don't set their own, and ${parent} publishes p=${policy} — mail from ${domain} may be ` +
    `${policy === 'reject' ? 'rejected outright' : 'quarantined'} under that inherited policy, even before DKIM ` +
    `is fully working here. Add a DMARC record at _dmarc.${domain} to set this subdomain's own policy.`;
}

export interface VerifyResult {
  spf: RecordCheckResult;
  dkim: RecordCheckResult;
  dmarc: RecordCheckResult;
  subdomainWarning: string | null;
}

export async function verifyDomain(domain: string, provider: SendingDomainProvider): Promise<VerifyResult> {
  const d = normalizeDomain(domain);
  const [spf, dkim, dmarc] = await Promise.all([checkSpf(d, provider), checkDkim(d, provider), checkDmarc(d)]);
  const subdomainWarning = await checkSubdomainInheritance(d, dmarc.found);
  return { spf, dkim, dmarc, subdomainWarning };
}
